const express = require('express');
const router = express.Router();

router.patch('/api/v1/credentials/passkeys/:credentialId/friendly-name', verifyUserAuth, async (req, res) => {
  const { credentialId } = req.params;
  const { label } = req.body;

  if (!label || label.length > 50) {
    return res.status(400).json({ error: 'Invalid label' });
  }

  const existing = await prisma.passkeyCredential.findFirst({
    where: { id: credentialId, userId: req.user.id }
  });
  if (!existing) {
    return res.status(404).json({ error: 'Passkey credential not found or unauthorized' });
  }

  const updated = await prisma.passkeyCredential.update({
    where: { id: credentialId },
    data: { nickname: label }
  });

  return res.json({ success: true, passkey: updated });
});
